"""USDC-funded fixed-range liquidity with one collection and complete exit."""

from almanak_v3.connectors.uniswap_v4.authoring import close_liquidity, open_liquidity, swap
from almanak_v3.connectors.uniswap_v4.authority import declared
from almanak_v3.connectors.uniswap_v4.models import Target
from almanak_v3.connectors.uniswap_v4.state import Decision, DecisionInput, OutcomeInput
from almanak_v3.dex_intents import CollectLiquidityFees, RevokeExchange
from almanak_v3.strategy_api import Memory


def capabilities(config):
    return declared(config)


def validate_config(config):
    if any(a.range is None for a in config.allocations):
        raise ValueError("LP allocations require explicit fixed ranges")


def decide(context: DecisionInput) -> Decision:
    for observed in context.observations:
        allocation = context.config.allocation(observed.allocation)
        intent = decide_allocation(context, allocation, observed)
        if intent is not None:
            return Decision(memory=context.memory, intent=intent)
    return Decision(memory=context.memory)


def decide_allocation(context, allocation, observed):
    started = context.memory.values.get("minted_at", {}).get(allocation.name)
    due = started is not None and observed.block.timestamp >= started + allocation.hold_seconds
    if context.teardown or due:
        return exit_allocation(allocation, observed)
    if observed.owned.position is not None:
        collected = context.memory.values.get("collected_at", {}).get(allocation.name)
        if collected is None and observed.block.timestamp >= started + allocation.collect_seconds:
            return CollectLiquidityFees[Target](
                target=observed.target,
                deadline=observed.block.timestamp + allocation.deadline_seconds,
            )
        return None
    if started is None:
        if not observed.owned.entry_complete and observed.entry_quote is not None:
            return swap(allocation, observed, observed.entry_quote)
        return open_liquidity(allocation, observed)
    return None


def exit_allocation(allocation, observed):
    if observed.owned.position is not None:
        return close_liquidity(allocation, observed)
    if observed.owned.inventory1.amount:
        return swap(allocation, observed, observed.exit_quote)
    if observed.needs_cleanup:
        return RevokeExchange[Target](target=observed.target)
    return None


def on_outcome(context: OutcomeInput) -> Memory:
    result = context.result
    if not (result.success and result.complete):
        return context.memory
    key = {"open_liquidity": "minted_at", "collect_liquidity_fees": "collected_at"}.get(
        result.intent.kind
    )
    if key is None:
        return context.memory
    previous = context.memory.values.get(key, {})
    if not isinstance(previous, dict):
        raise ValueError("outcome timestamps must map allocation names to block times")
    timestamps = dict(previous)
    timestamps[result.intent.target.allocation] = result.block.timestamp
    return Memory(version=context.memory.version, values={**context.memory.values, key: timestamps})
